import{_ as i,o as l,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-05-31","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-05-31","date":"2023-05-31T00:00:00.000Z","updated":"2023-06-01T00:00:00.000Z","tags":["Ceph","RGW","字符串优化","通知重试清理","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-31.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-31.md","lastUpdated":1780459816000}'),p={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-05-31.md"};function r(a,e,n,s,_,c){return l(),t("div",null,[...e[0]||(e[0]=[o("<p>本次会议主要讨论了Ceph RGW的几个重要议题，包括字符串优化、通知重试和清理机制，以及Bucket Level Redirect Zone的原型。</p><ol><li><p><strong>字符串优化</strong>：</p><ul><li>会议讨论了针对S3属性名称的优化方案，包括通过哈希将长字符串转换为短整数，以减少动态字符串分配和内存使用。</li><li>讨论了两种优化级别：在RGW内部进行转换和向客户端发送转换表。</li><li>决定首先在OSD层进行优化，隐藏在内部，不改变现有librados API。RGW可以管理一个本地缓存，从OSD获取转换表，避免全局同步问题。</li><li>需要开发测试工具来验证实际使用的属性名称数量。</li></ul></li><li><p><strong>通知重试和清理</strong>：</p><ul><li>讨论了通知重试机制，特别是在Kafka broker不可用时的行为。</li><li>当前设计是无限重试，直到队列满后向S3客户端发送慢速响应。</li><li>提出了设置重试次数上限和清理过期通知等改进方案。</li><li>决定通过邮件讨论，收集社区意见，确定最佳方案。</li></ul></li><li><p><strong>Bucket Level Redirect Zone 原型</strong>：</p><ul><li>讨论了相关PR，但未深入细节。</li></ul></li><li><p><strong>Reef多站点测试更新</strong>：</p><ul><li>Mark成功完成了4亿对象的同步负载测试，未发现回归问题。</li></ul></li></ol><p>会议决定了以下后续行动计划：</p><ul><li>继续讨论字符串优化方案，并开发测试工具。</li><li>发送邮件讨论通知重试和清理的最佳方案。</li><li>跟进Bucket Level Redirect Zone原型的进一步讨论。</li><li>继续Reef的多站点测试，确保无回归问题。</li></ul><p>这次会议对Ceph RGW的优化和功能改进具有重要意义，涉及到的关键技术包括Ceph、RGW、librados、libcephfs、S3、Kafka、RocksDB等。</p>",5)])])}const d=i(p,[["render",r]]);export{g as __pageData,d as default};
